mapper.select:
SELECT menu_id::TEXT AS row_id, p_menu_id, area, menu_nm, ordr, conn_ty, conn_id, link_url, target_yn, icon FROM t_menu WHERE use_yn = 'Y' AND area = #{area}
AND menu_id IN ( WITH RECURSIVE permitted AS ( SELECT a.menu_id FROM t_auth a
JOIN t_auth_user u ON u.authgrp_id = a.conn_id AND u.use_yn = 'Y' WHERE a.auth_gbn = 'GRP' AND a.menu_yn = 'Y' AND a.use_yn = 'Y' AND u.user_id = #{userId}
WHERE a.auth_gbn = 'GRP' AND a.menu_yn = 'Y' AND a.use_yn = 'Y' AND a.conn_id = 'GUEST'
), tree AS ( SELECT menu_id, p_menu_id FROM t_menu WHERE menu_id IN (SELECT menu_id FROM permitted) UNION SELECT m.menu_id, m.p_menu_id FROM t_menu m JOIN tree t ON m.menu_id = t.p_menu_id ) SELECT menu_id FROM tree )
ORDER BY p_menu_id, ordr

SELECT COUNT(*) FROM t_menu m JOIN t_auth a ON a.menu_id = m.menu_id AND a.auth_gbn = 'GRP' AND a.menu_yn = 'Y' AND a.use_yn = 'Y'
JOIN t_auth_user u ON u.authgrp_id = a.conn_id AND u.use_yn = 'Y' AND u.user_id = #{userId}
WHERE m.area = 'GEN' AND m.use_yn = 'Y' AND m.conn_ty = #{connTy} AND m.conn_id = #{connId}::integer AND a.conn_id = 'GUEST'

SELECT COUNT(*) FROM t_bbs b JOIN t_menu m ON m.conn_ty = 'MENU02' AND m.conn_id = b.bbsinfo_id AND m.area = 'GEN' AND m.use_yn = 'Y' JOIN t_auth a ON a.menu_id = m.menu_id AND a.auth_gbn = 'GRP' AND a.menu_yn = 'Y' AND a.use_yn = 'Y'
JOIN t_auth_user u ON u.authgrp_id = a.conn_id AND u.use_yn = 'Y' AND u.user_id = #{userId}
WHERE b.bbs_id = #{bbsId}::integer AND a.conn_id = 'GUEST'
